mapper.select:
select A.acctNo,
group_concat(A.acctName ORDER BY A.acctName separator ',') acctName, A.acctType, A.acctTypeCode, A.bankDep, A.inOutBank, A.inOutBankCode, A.corrNo, A.largePayno, A.blnArea, A.blnAreaCode, A.swiftCode from( select stl.ACCT_NO as acctNo, stl.ACCT_NAME as acctName, bok.ACCT_TYPE as acctType, bok.ACCT_TYPE as acctTypeCode, stl.BANK_DEP as bankDep, stl.IN_OUT_BANK as inOutBank, stl.IN_OUT_BANK as inOutBankCode, stl.CORR_NO as corrNo, stl.LARGE_PAYNO as largePayno, stl.BLN_AREA as blnArea, stl.BLN_AREA as blnAreaCode, stl.SWIFT_CODE as swiftCode from STL_CAPACCT_INFO stl inner join BOK_BOOKSET_CAPACCT_INFO bok on stl.ACCT_NO = bok.ACCT_NO where 1=1
and ( UPPER(stl.ACCT_NO) LIKE concat_ws('','%',UPPER(#{acct}),'%') OR UPPER(stl.ACCT_NAME) LIKE concat_ws('','%',UPPER(#{acct}),'%') )
and bok.ACCT_TYPE in
#{acctType}
) A group by A.acctNo, A.acctType, A.bankDep, A.inOutBank, A.corrNo, A.largePayno, A.blnArea, A.swiftCode

select stl.ACCT_NO as acctNo, stl.ACCT_NAME as acctName, bok.ACCT_TYPE as acctType, bok.ACCT_TYPE as acctTypeCode, stl.BANK_DEP as bankDep, stl.IN_OUT_BANK as inOutBank, stl.IN_OUT_BANK as inOutBankCode, stl.CORR_NO as corrNo, stl.LARGE_PAYNO as largePayno, stl.BLN_AREA as blnArea, stl.BLN_AREA as blnAreaCode, stl.SWIFT_CODE as swiftCode from STL_CAPACCT_INFO stl inner join BOK_BOOKSET_CAPACCT_INFO bok on stl.ACCT_NO = bok.ACCT_NO where 1=1
and stl.ACCT_NO = #{acctNo}
and LIMIT=1
